def simulate_draw(n):
    # Simulating the Simple Sequential Strategy (equivalent to W1's SAM)
    # This strategy is guaranteed to result in a draw for P_n
    sequence = []
    for i in range(1, n + 1):
        sequence.append((i, i)) # (move_number, chosen_value)

    # Check if all numbers were chosen
    if len(sequence) == n:
        return "Draw", sequence
    else:
        return "Loss", []

n_test = 12
outcome, sequence = simulate_draw(n_test)
print(f"Simulation for n={n_test}: Outcome={outcome}")
if outcome == "Draw":
    print(f"Move sequence length: {len(sequence)}")
